func (t Directive) Discriminator() (string, error) {
	var discriminator struct {
		Discriminator string `json:"type"`
	}
	err := json.Unmarshal(t.union, &discriminator)
	return discriminator.Discriminator, err
}

func (t Directive) ValueByDiscriminator() (interface{}, error) {
	discriminator, err := t.Discriminator()
	if err != nil {
		return nil, err
	}
	switch discriminator {
	case "collect":
		return t.AsCollectDirective()
	case "go_symbols":
		return t.AsGoSymbolsDirective()
	case "k8s_exec":
		return t.AsK8sExecDirective()
	case "k8s_sync":
		return t.AsK8sSyncDirective()
	case "renew_cert":
		return t.AsRenewCertDirective()
	case "scan_ssh":
		return t.AsScanSshDirective()
	case "sync_trust_bundle":
		return t.AsSyncTrustBundleDirective()
	default:
		return nil, errors.New("unknown discriminator value: " + discriminator)
	}
}

